def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Track statistics efficiently in one pass
    opp_c = 0
    my_c = 0
    last_my = None
    last_opp = None
    for a, b in history:
        if b == 'C':
            opp_c += 1
        if a == 'C':
            my_c += 1
    last_my, last_opp = history[-1]

    coop_rate = opp_c / n

    # Early game: establish cooperation
    if n <= 2:
        return 'C'

    # Compute recent opponent behavior
    recent_len = 10 if n >= 10 else n
    recent_opp = history[-recent_len:]
    recent_opp_c = 0
    for _, b in recent_opp:
        if b == 'C':
            recent_opp_c += 1
    recent_c_rate = recent_opp_c / recent_len

    # Detect runs of opponent defection / cooperation
    consec_d = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            consec_d += 1
        else:
            break
    consec_c = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'C':
            consec_c += 1
        else:
            break

    # Last two opponent moves for pattern detection
    prev_opp = history[-2][1] if n >= 2 else None

    # My last move
    prev_my = history[-2][0] if n >= 2 else None

    # ===== Endgame strategy =====
    # Last few rounds: exploit cooperative opponents
    remaining = 100 - n
    if remaining <= 1:
        # Final round: defect if opponent likely to cooperate
        if recent_c_rate > 0.3:
            return 'D'
        return 'D'
    if remaining <= 3:
        if recent_c_rate > 0.5:
            return 'D'
        if coop_rate > 0.6:
            return 'D'
        return 'D'

    # ===== Classify opponent =====
    # Pure cooperator: mutual C forever
    if opp_c == n:
        return 'C'
    # Pure defector
    if opp_c == 0:
        return 'D'

    # Almost always cooperative (and we haven't been exploited much recently)
    if coop_rate >= 0.9 and consec_d == 0:
        return 'C'

    # Very defection-heavy: defend
    if coop_rate < 0.3:
        # Occasionally try C to reset, but mostly D
        if consec_d >= 4 and rng.random() < 0.15:
            return 'C'
        return 'D'

    # ===== Reciprocation detection =====
    # Did opponent mirror my previous move?
    if n >= 4:
        mirror_hits = 0
        mirror_total = 0
        lookback = 8 if n >= 8 else n
        for i in range(n - lookback + 1, n):
            if history[i][1] == history[i - 1][0]:
                mirror_hits += 1
            mirror_total += 1
        if mirror_total > 0:
            mirror_score = mirror_hits / mirror_total
            # Strong reciprocator: cooperate to keep mutual C, but don't be a sucker
            if mirror_score > 0.75 and last_opp == 'C':
                return 'C'
            if mirror_score > 0.75 and last_opp == 'D':
                return 'C' if rng.random() < 0.85 else 'D'

    # ===== Core logic: forgiving tit-for-tat with anti-exploitation =====
    if last_opp == 'C':
        # Opponent cooperated
        if last_my == 'D':
            # We defected and they still cooperated -> reward with C
            if rng.random() < 0.9:
                return 'C'
            return 'C'
        # Mutually cooperating
        # Occasional probe only if opponent seems too nice and we want points
        if n >= 10 and coop_rate > 0.75 and remaining > 20:
            if rng.random() < 0.03:
                return 'D'
        return 'C'

    # Opponent defected last
    # If opponent just defected once but was cooperative in past, retaliate once then forgive
    if consec_d == 1:
        # Check if this is a first-time defection after a long cooperation streak
        if n >= 3 and coop_rate > 0.7 and consec_c >= 3:
            # Likely noise or test; retaliate but be ready to forgive
            return 'D'
        # Standard single retaliation
        return 'D'

    if consec_d == 2:
        # Two defections in a row: stronger retaliation
        if coop_rate > 0.6:
            # Was mostly cooperative: try to reset with C
            return 'C' if rng.random() < 0.4 else 'D'
        return 'D'

    # consec_d >= 3: sustained defection, defend hard
    if rng.random() < 0.1:
        return 'C'
    return 'D'
